import math

def calculate_expected_medals(n, probabilities):
    """
    Calculates the expected average number of medals won per year given the team formation probabilities.
    """
    if n == 0:
        return 0
    elif n == 1:
        return max(0, probabilities[0])
    else:
        max_medals = 0
        for p in probabilities:
            new_medals = max(max_medals * (1 - p), 0)
            max_medals = max(new_medals, max_medals + p)
        return max_medals * (1 - sum(probabilities[:n]))

def find_max_average_medals(n, probabilities):
    """
    Finds the maximum average probability of winning a medal using dynamic programming.
    """
    dp = [probabilities[0]] + [0] * (n - 1) 
    max_dp = 0
    for p in probabilities:
        dp[-1] = max(dp[-1], max_dp - p)
        for i in range(n - 2, -1, -1):
            next_dp = max(dp[i] * (1 - p) + p * (dp[i+1] + dp[i]), dp[i])
            dp[i] = next_dp
            max_dp = max(max_dp, dp[i])
    total_medals = 0
    for i in range(n):
        total_medals += max(dp[i], 0)
    return total_medals / n

def solve():
    n = int(input().strip())
    probabilities = list(map(float, input().strip().split()))

    print("The maximum average probability of winning a medal per year is:", find_max_average_medals(n, probabilities))

solve()
