from collections import defaultdict

def paint_regions(n, m, x, a, b):
    prefix_sum = [0]
    for i in range(n):
        prefix_sum.append(prefix_sum[-1] + b[i])

    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j + 1] + dp[i - 1][min(j + 1, m)]

    paint_q = [deque([]) for _ in range(n + 1)]
    paint_q[n].append(0)
    for i, query in enumerate(zip(a, dp)):
        ai, aj = query
        for col in range(i + 1, 0, -1):
            paint_q[col].append(ai + bj)
        if j + 1 <= m:
            update_paint(paint_q, set(range(i + 1, col + 1)), m)
        else:
            update_paint(paint_q, set(range(i + 1, col + 1)), j + 1)

    regions = 0
    for paint in paint_q:
        added = set(paint)
        j_set = set(paint_q[0])
        while added:
            paint = added.pop()
            j_set -= set([i for i in range(n + 1) if dp[i][paint] and min(j + 1, m) > paint])

            if not j_set:
                added = ()
                regions += 1
            else:
                removed = []
                for j in range(n):
                    # Update dp[j+1][paint + b]
                    if j + 2 < len(paint_q[j]) and dp[j + 1][paint + b[j + 1]] and (paint + b[j + 1] in j_set):
                        added.add(paint + b[j + 1])
                    else:
                        dp[j + 1][paint + b[j + 1]] = dp[j + 1][paint]
                        removed.append(dp[j + 1])
                    # Update dp[j][i-prime], if there is enough paint to paint the (i-prime, j)
                    if j + min(j + 1, m) - paint - b[$j] <= m:
                        dp[j][paint - (x - a[j] + b[j])] &= ~dp[j + 1]

    return regions

def update_paint(clock, removed, dimension):
    for i in range(n + 1):
        clock[i] &= ~{i + dimension + j for j in removed}
    clock[-1] &= ~{i * dimension + dimension for i in range(n + 1) if clock[i] & {i + dimension}}


# Example usage
n, m, x = map(int, input().split())
a = list(map(int, input().split()))
b = list(map(int, input().split()))

print(paint_regions(n, m, x, a, b))
