import math

def get_min_expectation(n, pi):
    min_expectation = 0
    for i in range(n):
        pi[i] /= 100  # Convert percent to probability
        if pi[i] == 1: 
            min_expectation += (i + 1) * (n - sum(pi))
        else:
            k1, k2 = 0, 0
            for i in range(n):
                if pi[i] == 1 and pi[i - 1] == 0:
                    k1 = i + 1
                elif pi[i] == 1 and pi[i - 1] == 1 and k1:
                    k2 = i + 1
            if k1 and k2:
                min_expectation += (i + 1) * (i + 1 + k1 + k2)
    return math.floor(min_expectation)

