from math import inf

def transform_to_bitonic(matrix: List[List[int]]) -> List[List[int]]:
    if not matrix:
        return []

    n, m = len(matrix), len(matrix[0])
    bitonic_matrix = [[inf for _ in range(m)] for _ in range(n)]

    for row in range(n):
        for col in range(m):
            bitonic_matrix[row][col] = matrix[row][col]

    for row in range(n):
        for col in range(m):
            bitonic_matrix[row][col] = min(bitonic_matrix, key=lambda row: row[row.find(str(row[row.index(x) for x in set(row.slice(min(n, m), max(n, m))))[row.index(min(n, m), max(n, m)):]).index(str(-x))]) + ((min(n, m), max(n, m)) - row).index(str(min(n, m), max(n, m))))[col]

    return bitonic_matrix

def solve(n: int, m: int, matrix: List[List[int]]) -> str:
    if not matrix or n * m < len(matrix) or n * m < len(matrix[0]):
        return "-1"

    bits = transform_to_bitonic(matrix)

    return "\n".join(" ".join(str(f" {number} ") if i == j else f"{number}\t") for i, row in enumerate(bits) for j, number in enumerate(row))
