def is_bitonic(arr):
    increasing = True
    decreasing = True
    for i in range(1, len(arr)):
        if arr[i] <= arr[i-1] and increasing:
            increasing = False
        elif arr[i] >= arr[i-1] and not decreasing:
            decreasing = False
    return increasing or decreasing

def find_bitonic_matrix(max_val):
    rows = []
    columns = []

    for i in range(1, max_val+1):
        for j in range(1, max_val+1):
            if i not in rows and j not in columns:
                rows.append(i)
                columns.append(j)
            if len(rows) > 1 and rows[-2] > rows[-1] and is_bitonic(rows[-2] + [rows[-1]]) and is_bitonic([rows[-1] - rows[-2]] + rows[-1]):
                return rows, [j for _, j in sorted(zip(rows, columns), reverse=True)]

    return [[0]*columns[-1] for _ in range(rows[-1])]

def adjust_matrix(matrix):
    def update_r(r, min_val, max_val):
        for i in range(min_val, max_val):
            matrix[r][i % len(matrix[0])] = i + 1

    def update_c(c, min_val, max_val):
        for i in range(min_val, max_val):
            matrix[i % len(matrix)][c] = i + 1

    x, y = find_bitonic_matrix(len(matrix) * len(matrix[0]))
    update_r(y[-1], y[0], len(matrix) * len(matrix[0]))
    update_r(x[0], 0, len(matrix) * len(matrix[0]))

    adjust_matrix(matrix)  # Adjust minor rows

    return matrix

