import numpy as np

def is_bitonic(arr):
    increasing_test = arr[:-1] < arr[1:]
    decreasing_test = arr[:-1] > arr[1:]
    return increasing_test.all() and decreasing_test.any()

def find_solution(n, m):
    if n > m:
        return -1  # Not possible for a square matrix

    max_val = n * m
    A = np.arange(1, max_val + 1).reshape(n, m)

    # Generate possible solutions by swapping elements at indices (1,2) and (n, m) for each row
    # and ensuring Y is bitonic in each row
    for i in range(n):
        max_rows = np.max(A[i, :], axis=0)
        max_cols = np.max(A[:, i], axis=0)
        for j in range(m):
            if A[i, j] != max_rows[j] and A[i, j] != max_cols[j]:
                A[i, j], A[i, j + 1] = A[i, j + 1], A[i, j]

    # Ensure X is bitonic in each row
    if not all(is_bitonic(A[i]) for i in range(n)):
        return -1

    return A

# Example usage:
n = 3
m = 4
solution_matrix = find_solution(n, m)
for row in solution_matrix:
    print(" ".join(map(str, row)))
