def bfs(ini, fi, grid, k):
    n, m, k = len(grid), len(grid[0]), len(set(ini) - {"S", "T"})
    dist = [[float("inf")] * (k + 1) for _ in range(n * m + 2)]
    dist[m * n] = 0
    que = deque([(m * n, ini)])

    while que:
        r, c = que.popleft()

        if (r // n, r % n) == (fi[0], fi[1]):
            break

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                new_c = [c]

                for nc_ in c:
                    nnr, nnc = nr * m + nc_
                    if grid[(nr, nc)].isdigit() or (nr, nc != "T" and nc in new_c):
                        new_c.append(nc)
                    else:
                        break

                for nc_ in new_c:
                    # Multiple types
                    if not grid[(nr_, nc_)].isdigit() and nc_ + "S" in ini:
                        if grid[(nr_, nc_)].isdigit() or (nr_, nc_ != "S" and nc in ini):
                            continue
                        if dist[nr * m + nc_] > dist[r * m + c] + 1:
                            continue
                    # A move just leaves us with available/other types.
                    if grid[(nr, nc)].isdigit() and dist[r * m + c] + 1 >= rdr:
                        continue

                    que.append((nr * m + nc, tuple(new_c)))
                    dist[nr * m + nc] = dist[r * m + c] + 1

    return dist[m * n] + 1 if (dist[r * m + c] := dist[m * n]) != float("inf") and dist[m * n] < float("inf") else -1

