    t = list(grid[fi[0] - 1].strip())
    while "T" in t:
        tbody[ty:].append(t.index("T"))
        t.pop(t.index("T"))

    for nr in tbody:
        for node in deque(reversed(nr)):
            if node != "S":
                ini.append(node)

    bad = []
    for ind, _ in enumerate(ini):
        if ind < len(ini) - K and ini[ind] in set(ini[ind + ind:ind + K + 1]):
            bad.append(True)
        else:
            bad.append(False)

    for ind, _ in enumerate(bad):
        if not bad[ind]:
            ini.pop(ind)

    ini = ini[gix - 1:gui]

    ini.sort()

