                xi_plus_1 = f(generator_coefficients[j]) + f(generator_restrictions[j])
                if xi_plus_1[0][1] < f(generator_coefficients[i]) + b[i][1]:
                    b[i][1] = f(generator_coefficients[i]) + f(generator_restrictions[j])[1]

    for i in range(n):
        max_output = max(max_output, sum(generator_coefficients[i] + b[i][1]) 
                    for i in range(n) 
                    if (i, i+1) != tuple(b))

    return max_output

