import sys

def dijkstra(map, k, source, target):
    n, m = len(map), len(map[0])
    dist = [[[9999999] * 51 for _ in range(m)] for _ in range(n)]
    dist[source[0]][source[1]][0] = 0

    for w in range(51):
        for x in range(n):
            for y in range(m):
                if w == 0 and (map[x][y] == 'S' if x != source[0] or y != source[1] else False):
                    dist[x][y][w] = 0
                elif w > 0 and map[x][y] != 'S' and map[x][y] != 'T':
                    if dist[x][y][w-1] + 1 < dist[x][y][w]:
                        dist[x][y][w] = dist[x][y][w-1] + 1

    for kth_type in range(1, k+1):
        for x in range(n):
            for y in range(m):
                init = False
                if map[x][y] == 'T' and kth_type == 1: init = True
                elif map[x][y] == 'S' and kth_type == k: init = True

                if dist[x][y][kth_type-1] + int(init) < dist[x][y][kth_type]:
                    dist[x][y][kth_type] = dist[x][y][kth_type-1] + 1

    ans = ''
    for x in range(n):
        for y in range(m):
            if dist[x][y][k] < 9999999 and x != source[0] or y != source[1]:
                ans += chr(x + ord('a') if x < n-1 else 'A' + (x + 1 - n) * 50)
    return ans

