from collections import defaultdict

def num_badly_painted_regions(n, m, x, a, b):
    # Create adjacency list for the grid using lists of lists.
    grid = [[0 for _ in range(m)] for _ in range(n)]

    for i in range(n):
        grid[i] = list(a[i])

    for j in range(m):
        for i in range(n):
            grid[i][j] += b[j]

    count = 0
    # Find all valid bad cells.
    for i in range(n):
        for j in range(m):
            if grid[i][j] <= x:
                count += 1
                for x in range(max(0, grid[i][j] - x), n * m):
                    # Remove this from grid and break.
                    grid[x // m][x % m] -= 2
                    if grid[x // m][x % m] < 0:
                        grid[x // m][x % m] = 0
                    break

    return count

