import sys

def kth_label_name(n: int, m: int, k: int, s: str) -> str:
    """
    Computes the k-th lexicographically minimal arrangement of meeting rooms.

    :param n: Length of string s.
    :param m: Number of planned meeting rooms.
    :param k: Number of the interesting label.
    :param s: String representing the building side.
    :return: Name of the meeting room printed on k-th label.
    """
    letters = {i: c for i, c in enumerate(s)}
    visited = [False] * n

    def backtrack(position: int, width: int) -> str:
        if width == m:
            return ""
        if position == n:
            k -= 1
            if k == 0:
                return ""
            return backtrack(0, 1)

        names = []

        for i in range(position, min(n, position + width + 1)):
            if not visited[i] and letters[i] != '?':
                visited[i] = True
                names.append(letters[i])
                if backtrack(i + 1, width + 1):
                    return ""
                visited[i] = False
        return "".join(sorted(names))

    return backtrack(0, 1)

# Reading input
