from bisect import bisect_right

def find_meeting_room(s, m):
    n = len(s)
    if m == 1:
        return s

    known_labels = []

    for i in range(n - n//m + 1):
        for j in range(n//m, i - 1, -1):
            label = s[j:j + m]
            index = bisect_right(known_labels, label)
            if index == len(known_labels):
                known_labels.append(label)
            else:
                known_labels[index] = label

    return known_labels[bisect_right(known_labels, find_meeting_room(s, m))]

